using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 breaking change: discriminator property renamed to "$type".
            // Restore EF8 name so existing documents (which have "Discriminator") still load.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 breaking change: id format changed from "EntityName|Key" to just "Key".
            // Restore EF8 format so existing ids like "Product|123" keep working.
            entity.HasKey(p => p.Id);
            entity.Property(p => p.Id)
                  .ToJsonProperty("id")
                  .HasValueGenerator<LegacyCosmosIdValueGenerator>();
        });
    }
}

// Reproduces the EF8 "TypeName|Key" id format for backward compatibility.
using Microsoft.EntityFrameworkCore.ValueGeneration;
using Microsoft.EntityFrameworkCore.ChangeTracking;
class LegacyCosmosIdValueGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(EntityEntry entry)
        => $"Product|{entry.Property("Id").CurrentValue}";
}

class Product { public int Id { get; set; } public string Sku { get; set; } }

